#pragma once

#include <array>
#include <cstddef>
#include <cstdint>
#include <span>
#include <string_view>
#include <vector>

namespace epochengine::gui_lib
{
    struct Vec2 final
    {
        float x{};
        float y{};
    };

    struct Rect final
    {
        Vec2 position{};
        Vec2 size{};
    };

    namespace font
    {
        inline constexpr std::uint32_t glyph_width = 5;
        inline constexpr std::uint32_t glyph_height = 7;
        inline constexpr std::uint32_t glyph_advance = 6;
        inline constexpr std::uint32_t line_advance = 9;

        struct BitmapGlyph final
        {
            std::array<std::uint8_t, glyph_height> rows{};
        };

        [[nodiscard]] constexpr BitmapGlyph default_glyph(char character) noexcept
        {
            char c = character;
            if (c >= 'a' && c <= 'z')
                c = static_cast<char>(c - 'a' + 'A');

            switch (c)
            {
            case 'A': return {{0x0e, 0x11, 0x11, 0x1f, 0x11, 0x11, 0x11}};
            case 'B': return {{0x1e, 0x11, 0x11, 0x1e, 0x11, 0x11, 0x1e}};
            case 'C': return {{0x0f, 0x10, 0x10, 0x10, 0x10, 0x10, 0x0f}};
            case 'D': return {{0x1e, 0x11, 0x11, 0x11, 0x11, 0x11, 0x1e}};
            case 'E': return {{0x1f, 0x10, 0x10, 0x1e, 0x10, 0x10, 0x1f}};
            case 'F': return {{0x1f, 0x10, 0x10, 0x1e, 0x10, 0x10, 0x10}};
            case 'G': return {{0x0f, 0x10, 0x10, 0x17, 0x11, 0x11, 0x0f}};
            case 'H': return {{0x11, 0x11, 0x11, 0x1f, 0x11, 0x11, 0x11}};
            case 'I': return {{0x1f, 0x04, 0x04, 0x04, 0x04, 0x04, 0x1f}};
            case 'J': return {{0x07, 0x02, 0x02, 0x02, 0x12, 0x12, 0x0c}};
            case 'K': return {{0x11, 0x12, 0x14, 0x18, 0x14, 0x12, 0x11}};
            case 'L': return {{0x10, 0x10, 0x10, 0x10, 0x10, 0x10, 0x1f}};
            case 'M': return {{0x11, 0x1b, 0x15, 0x15, 0x11, 0x11, 0x11}};
            case 'N': return {{0x11, 0x19, 0x19, 0x15, 0x13, 0x13, 0x11}};
            case 'O': return {{0x0e, 0x11, 0x11, 0x11, 0x11, 0x11, 0x0e}};
            case 'P': return {{0x1e, 0x11, 0x11, 0x1e, 0x10, 0x10, 0x10}};
            case 'Q': return {{0x0e, 0x11, 0x11, 0x11, 0x15, 0x12, 0x0d}};
            case 'R': return {{0x1e, 0x11, 0x11, 0x1e, 0x14, 0x12, 0x11}};
            case 'S': return {{0x0f, 0x10, 0x10, 0x0e, 0x01, 0x01, 0x1e}};
            case 'T': return {{0x1f, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04}};
            case 'U': return {{0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x0e}};
            case 'V': return {{0x11, 0x11, 0x11, 0x11, 0x11, 0x0a, 0x04}};
            case 'W': return {{0x11, 0x11, 0x11, 0x15, 0x15, 0x15, 0x0a}};
            case 'X': return {{0x11, 0x11, 0x0a, 0x04, 0x0a, 0x11, 0x11}};
            case 'Y': return {{0x11, 0x11, 0x0a, 0x04, 0x04, 0x04, 0x04}};
            case 'Z': return {{0x1f, 0x01, 0x02, 0x04, 0x08, 0x10, 0x1f}};
            case '0': return {{0x0e, 0x11, 0x13, 0x15, 0x19, 0x11, 0x0e}};
            case '1': return {{0x04, 0x0c, 0x04, 0x04, 0x04, 0x04, 0x0e}};
            case '2': return {{0x0e, 0x11, 0x01, 0x02, 0x04, 0x08, 0x1f}};
            case '3': return {{0x1e, 0x01, 0x01, 0x0e, 0x01, 0x01, 0x1e}};
            case '4': return {{0x02, 0x06, 0x0a, 0x12, 0x1f, 0x02, 0x02}};
            case '5': return {{0x1f, 0x10, 0x10, 0x1e, 0x01, 0x01, 0x1e}};
            case '6': return {{0x0e, 0x10, 0x10, 0x1e, 0x11, 0x11, 0x0e}};
            case '7': return {{0x1f, 0x01, 0x02, 0x04, 0x08, 0x08, 0x08}};
            case '8': return {{0x0e, 0x11, 0x11, 0x0e, 0x11, 0x11, 0x0e}};
            case '9': return {{0x0e, 0x11, 0x11, 0x0f, 0x01, 0x01, 0x0e}};
            case '-': return {{0x00, 0x00, 0x00, 0x1f, 0x00, 0x00, 0x00}};
            case '.': return {{0x00, 0x00, 0x00, 0x00, 0x00, 0x06, 0x06}};
            case ':': return {{0x00, 0x06, 0x06, 0x00, 0x06, 0x06, 0x00}};
            case '/': return {{0x01, 0x02, 0x02, 0x04, 0x08, 0x08, 0x10}};
            case '_': return {{0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x1f}};
            case '+': return {{0x00, 0x04, 0x04, 0x1f, 0x04, 0x04, 0x00}};
            case '!': return {{0x04, 0x04, 0x04, 0x04, 0x04, 0x00, 0x04}};
            case '?': return {{0x0e, 0x11, 0x01, 0x02, 0x04, 0x00, 0x04}};
            case ',': return {{0x00, 0x00, 0x00, 0x00, 0x06, 0x04, 0x08}};
            case ';': return {{0x00, 0x06, 0x06, 0x00, 0x06, 0x04, 0x08}};
            case '=': return {{0x00, 0x00, 0x1f, 0x00, 0x1f, 0x00, 0x00}};
            case '(': return {{0x02, 0x04, 0x08, 0x08, 0x08, 0x04, 0x02}};
            case ')': return {{0x08, 0x04, 0x02, 0x02, 0x02, 0x04, 0x08}};
            case '[': return {{0x0e, 0x08, 0x08, 0x08, 0x08, 0x08, 0x0e}};
            case ']': return {{0x0e, 0x02, 0x02, 0x02, 0x02, 0x02, 0x0e}};
            case ' ': return {};
            default: return {{0x0e, 0x11, 0x01, 0x02, 0x04, 0x00, 0x04}};
            }
        }
    }

    namespace rounded_rect
    {
        struct CornerRadii final
        {
            float top_left{};
            float top_right{};
            float bottom_right{};
            float bottom_left{};
        };

        struct RoundedRectOptions final
        {
            Rect bounds{};
            CornerRadii radii{12.0F, 12.0F, 12.0F, 12.0F};
            float border_width{};
            std::uint32_t segments_per_corner{8U};
        };

        struct RoundedRectMesh final
        {
            std::vector<Vec2> vertices{};
            std::vector<std::uint32_t> fill_indices{};
            std::vector<std::uint32_t> border_indices{};
            Rect bounds{};
            CornerRadii radii{};
            float border_width{};
            std::uint32_t outer_first{};
            std::uint32_t outer_count{};
            std::uint32_t inner_first{};
            std::uint32_t inner_count{};
            bool valid{};

            [[nodiscard]] std::span<const Vec2> outer_contour() const noexcept;
            [[nodiscard]] std::span<const Vec2> inner_contour() const noexcept;
        };

        [[nodiscard]] CornerRadii normalize_corner_radii(Rect bounds, CornerRadii radii) noexcept;
        [[nodiscard]] RoundedRectMesh make_rounded_rect_mesh(const RoundedRectOptions& options);
    }
}
